(function(){
'use strict';
const pages=['Lead pricing','Kitset inventory','Approved documents','Supply agreements','Marketplace fees','Notifications'];
const categories={ 'Primary structure':['Portal frames / columns','Rafters / beams','Bracing members','Base plates / connections'], 'Secondary steel':['Wall girts','Roof purlins','Eave struts','Cleats / brackets'], 'Roof & wall envelope':['Roof sheets','Wall cladding','Ridge / barge flashings','Apron / corner flashings','Closures / sealants','Roof underlay','Wall underlay'], 'Fixings & hardware':['Structural bolts / washers','Cladding screws','Anchor assemblies','Rivets / tapes'], 'Openings':['Windows / glazing','External doors','Garage / roller doors','Opening flashings'], 'Rainwater':['Gutters','Downpipes','Outlets / brackets'], 'Optional inclusions':['Insulation','Internal framing','Lining package'], 'Delivery & records':['Packing schedule','Shop drawings','Installation instructions','Product warranties']};
function init(c){for(const k of ['quotes','leadNotes','inventory','documents','notifications','agreements'])c.store[k] ||= [];c.store.fees ||= {contractorMonthly:null,customerTender:null,gstRate:15};c.store.preferences ||= {};}
const uid=()=>globalThis.crypto?.randomUUID?.()||`staff-${Date.now()}-${Math.random()}`;
const stamp=()=>new Date().toISOString();
function refresh(p,c){c.save();c.navigate(p)}
function emit(c,title,message,kind='update'){c.notify({title,message,roles:['staff','customer','contractor'],projectId:c.projectId,kind})}
function option(xs,v,e){return xs.map(x=>`<option ${x===v?'selected':''}>${e(x)}</option>`).join('')}
function projectSelect(c){return `<label>Project<select id="staff-project">${c.projects.map(p=>`<option value="${c.escape(p.id)}" ${p.id===c.projectId?'selected':''}>${c.escape(p.name)} · ${c.escape(p.id)}</option>`).join('')}</select></label>`}
function frame(title,sub,body){return `<div class="staff-module"><div class="heading"><div><div class="eyebrow">SHED HOUSE / BUSINESS OPERATIONS</div><h1>${title}</h1><p>${sub}</p></div><span class="tag amber">Local demo</span></div>${body}</div>`}
function render(page,c){init(c);const e=c.escape,s=c.store,pr=c.projectId;const card=(title,b)=>`<section class="card"><h2>${title}</h2>${b}</section>`;
if(page==='Lead pricing'){const selected=s.staffLead??0;const lead=c.leads[selected];const q=s.quotes.find(x=>x.leadIndex===selected)||{};const lines=q.lines||[{name:'Kitset supply',qty:1,rate:0},{name:'Engineering & design',qty:1,rate:0},{name:'Freight',qty:1,rate:0}];const subtotal=lines.reduce((n,x)=>n+x.qty*x.rate,0);return frame('From enquiry to agreement.','Build a transparent estimate, record the conversation and move each lead towards contract.',`<div class="staff-grid">${card('Lead workspace',`<label>Lead<select id="staff-lead">${c.leads.map((l,i)=>`<option value="${i}" ${i===selected?'selected':''}>${e(l.name)}</option>`).join('')}</select></label>${lead?`<p>${e(lead.region)} · ${e(lead.source)}</p><form id="staff-quote"><label>Pipeline<select name="stage">${option(['New lead','Qualified','Pricing','Proposal','Negotiation','Contract ready','Confirmed'],q.stage||lead.stage,e)}</select></label><label>Quote reference<input name="reference" value="${e(q.reference||'DRAFT-001')}" required></label><label>Estimate valid until<input name="validUntil" type="date" value="${e(q.validUntil||'')}"></label><div id="staff-lines">${lines.map((x,i)=>`<div class="staff-price-line"><input aria-label="Item ${i+1}" name="item${i}" value="${e(x.name)}" required><input aria-label="Quantity ${i+1}" name="qty${i}" type="number" min="0" step="0.01" value="${x.qty}" required><input aria-label="Rate ${i+1}" name="rate${i}" type="number" min="0" step="0.01" value="${x.rate}" required></div>`).join('')}</div><button type="button" class="secondary" id="staff-add-line">+ Price item</button><label>Inclusions, exclusions & assumptions<textarea name="scope">${e(q.scope||'Confirm engineering, site access, delivery and exclusions before issuing.')}</textarea></label><p>Saved estimate: <strong>${c.money(subtotal)}</strong> excl. GST · ${c.money(subtotal*1.15)} incl. 15% GST</p><p class="small">Pricing is indicative until authorised. Confirmed here records demo pipeline status; it does not execute a contract.</p><button class="primary">Save pricing & pipeline</button></form>`:'<p>Add a lead in Sales & CRM first.</p>'}`)}${card('Conversation & lead notes',`<form id="staff-note"><label>Source<select name="source"><option>Manual conversation</option><option>Pasted email</option><option>Phone call</option><option>Site meeting</option></select></label><label>Sender / contact<input name="contact" placeholder="Who supplied this information?"></label><label>Email subject / reference<input name="reference"></label><label>Information received<textarea name="text" required placeholder="Paste email content or write a note…"></textarea></label><p class="small">Email content is pasted manually. No mailbox is connected.</p><button class="primary">Add lead note</button></form><div class="staff-records">${s.leadNotes.filter(n=>n.leadIndex===selected).map(n=>`<article><strong>${e(n.source)} · ${e(n.contact||'Team note')}</strong><p>${e(n.text)}</p><span class="small">${e(n.reference||'')} · ${e(n.createdAt)}</span></article>`).join('')||'<p>No notes yet.</p>'}</div>`)}</div>`)}
if(page==='Kitset inventory'){const rows=s.inventory.filter(x=>x.projectId===pr);return frame('Every component accounted for.','A categorized ordering register, shared clearly with your customer and contractor.',projectSelect(c)+`<div class="banner"><div><h2>Project inventory template</h2><p>Populate from approved engineering and supplier schedules. Template quantities start at zero; this is not a structural bill of materials.</p></div><button class="primary" id="staff-seed">Create template</button></div>`+Object.keys(categories).map(cat=>card(cat,`<div class="table-wrap"><table><thead><tr><th>Component / specification</th><th>Qty / unit</th><th>Supplier / order reference</th><th>Order status</th><th></th></tr></thead><tbody>${rows.filter(x=>x.category===cat).map(x=>`<tr><td><strong>${e(x.name)}</strong>${e(x.spec||'Specification required')}</td><td>${x.qty} ${e(x.unit)}</td><td>${e(x.supplier||'Unassigned')}<br>${e(x.orderReference||'')}</td><td>${e(x.status)}</td><td><button class="link" data-staff-edit="${e(x.id)}">Edit</button></td></tr>`).join('')||'<tr><td colspan="5">No items in this category.</td></tr>'}</tbody></table></div>`)).join('')+card('Add or edit component',`<form id="staff-inventory" class="staff-form"><input type="hidden" name="id"><label>Category<select name="category">${option(Object.keys(categories),'',e)}</select></label><label>Item<input name="name" required></label><label>Specification / drawing reference<input name="spec"></label><label>Quantity<input name="qty" type="number" min="0" step="0.01" value="0" required></label><label>Unit<input name="unit" value="ea" required></label><label>Supplier<input name="supplier"></label><label>Order reference<input name="orderReference"></label><label>Status<select name="status">${option(['To specify','Ready to order','Ordered','Manufacturing','Dispatched','Delivered','Issue raised'],'',e)}</select></label><button class="primary">Save item</button></form>`))}
if(page==='Approved documents')return frame('One approved source of truth.','Register consent documents and make approved versions available across the project.',projectSelect(c)+`<div class="staff-grid">${card('Add project document',`<form id="staff-document"><label>Document name<input name="name" required></label><label>Type<select name="type">${option(['Building consent','Approved plans','Engineering','Specification','Inspection record','Other'],'',e)}</select></label><label>Version / consent reference<input name="version" required></label><label>Status<select name="status">${option(['Draft','Submitted','Approved','Superseded'],'',e)}</select></label><label>Secure HTTPS document / Objective Build project link<input name="url" type="url" placeholder="https://…" required></label><label>Visibility<select name="audience"><option value="all">Shed House, customer & contractor</option><option value="customer">Shed House & customer</option><option value="staff">Shed House only</option></select></label><button class="primary">Register document</button></form><p class="small">Links require the external service’s own access permissions. Approval status is entered by SH; verify against the consent authority. Objective Build integration is a manual link at this stage.</p>`)}${card('Document register',s.documents.filter(d=>d.projectId===pr).map(d=>`<article class="staff-record"><span class="tag ${d.status==='Approved'?'':'grey'}">${e(d.status)}</span><h3>${e(d.name)}</h3><p>${e(d.type)} · ${e(d.version)} · ${e(d.visibility.join(', '))}</p><a href="${e(safeUrl(d.url))}" target="_blank" rel="noopener noreferrer">Open document ↗</a></article>`).join('')||'<p>No documents registered for this project.</p>')}</div>`);
if(page==='Supply agreements'){let a=s.agreements.find(x=>x.projectId===pr)||{};return frame('A clear supply agreement.','Prepare project particulars and a reviewable kitset supply framework.',projectSelect(c)+`<div class="banner"><div><h2>Draft for professional review</h2><p>Not a legal template ready for execution. Confirm applicability of construction payment rules, consumer protections and project-specific obligations before use.</p></div></div><div class="staff-grid">${card('Project particulars',`<form id="staff-agreement"><label>Customer legal name<input name="customer" value="${e(a.customer||c.project?.client||'')}" required></label><label>Site / delivery address<input name="site" value="${e(a.site||'')}" required></label><label>Supply price NZD excluding GST<input type="number" min="0" step="0.01" name="price" value="${e(a.price||'')}"></label><label>Payment milestones<textarea name="payments">${e(a.payments||'Specify deposit, production, dispatch and final amounts, due dates and payment process. Review construction payment requirements where applicable.')}</textarea></label><label>Delivery, risk & exclusions<textarea name="terms">${e(a.terms||'Attach approved kitset schedule and drawings. Specify exclusions, access/unloading, delivery dates, title/risk, damage checks, defects, warranties, written variations, cancellation, delays and dispute resolution.')}</textarea></label><label>Review notes<textarea name="review">${e(a.review||'Solicitor review required. Do not exclude non-excludable consumer guarantees. Confirm whether this supply arrangement is a construction contract and any relevant residential building obligations.')}</textarea></label><button class="primary">Save agreement draft</button></form>`)}${card('Agreement checklist',`<ol class="staff-checklist"><li>Parties, site and authority to contract</li><li>Approved drawings and categorized supply schedule</li><li>Price, GST, exclusions and payment milestones</li><li>Delivery, access, risk, title and acceptance</li><li>Written variation and approval process</li><li>Defects, warranties and consumer guarantees</li><li>Delay, cancellation and dispute procedure</li><li>Construction payment provisions where applicable</li><li>Legal review, version control and signatures</li></ol><p><strong>Current status: Unreviewed draft</strong></p><p class="small">No e-signature or binding acceptance is enabled.</p><p><a target="_blank" rel="noopener" href="https://www.legislation.govt.nz/act/public/2002/0046/latest/whole.html">Construction Contracts Act 2002 ↗</a></p><p><a target="_blank" rel="noopener" href="https://www.legislation.govt.nz/act/public/1993/0091/latest/whole.html">Consumer Guarantees Act 1993 ↗</a></p>`)}</div>`)}
if(page==='Marketplace fees'){const f=s.fees;return frame('A marketplace with clear costs.','Configure proposed commercial fees before activating any paid service.',`<div class="staff-grid">${card('Fee configuration',`<form id="staff-fees"><label>Contractor subscription · NZD / month excluding GST<input name="contractorMonthly" type="number" min="0" step="0.01" value="${f.contractorMonthly??''}" placeholder="Not established"></label><label>Customer optional tender listing · NZD / kitset project excluding GST<input name="customerTender" type="number" min="0" step="0.01" value="${f.customerTender??''}" placeholder="Not established"></label><p class="small">GST: 15%. Blank means not established; zero explicitly means free. No billing or collection is enabled.</p><button class="primary">Save proposed fees</button></form>`)}${card('Commercial model',`<h3>Contractor membership</h3><p>${f.contractorMonthly===null?'Price not established':`${c.money(f.contractorMonthly)} + GST / month (${c.money(f.contractorMonthly*1.15)} including GST)`}</p><p>Define access, subscription renewal, cancellation, contractor verification and dispute support before launch.</p><h3>Customer tender option</h3><p>${f.customerTender===null?'Price not established':`${c.money(f.customerTender)} + GST once per project (${c.money(f.customerTender*1.15)} including GST)`}</p><p>Optional, with explicit customer selection. Confirm scope readiness, builder coverage, refund rules and service terms before charging.</p>`)}</div>`)}
if(page==='Notifications'){const pref=s.preferences.staff||{};return frame('The right message. At the right time.','A shared activity inbox for decisions, changes and project handovers.',`<div class="staff-grid">${card('Team inbox',s.notifications.filter(n=>!n.roles||n.roles.includes('staff')).map(n=>`<article class="staff-record ${n.readBy?.includes('staff')?'staff-read':''}"><span class="tag">${e(n.kind||'Update')}</span><h3>${e(n.title)}</h3><p>${e(n.message)}</p><span class="small">${e(n.projectId||'Business')} · ${e(n.createdAt||'')}</span> <button class="link" data-staff-read="${e(n.id)}">Mark read</button></article>`).join('')||'<p>No notifications yet. Project changes will appear here.</p>')}${card('Notification preferences',`<form id="staff-preferences"><label><input type="checkbox" name="inApp" ${pref.inApp!==false?'checked':''}> In-app activity inbox</label><label><input type="checkbox" name="email" ${pref.email?'checked':''}> Email digest (planned)</label><label><input type="checkbox" name="urgentSms" ${pref.urgentSms?'checked':''}> Urgent SMS escalation (planned)</label><label>Digest frequency<select name="digest">${option(['Daily','Weekly','Immediate'],pref.digest||'Daily',e)}</select></label><button class="primary">Save preferences</button></form><h3>Recommended production approach</h3><p>Use the in-app inbox as the audit trail, email for required decisions and digest updates, and opt-in SMS for urgent inspection or site blockers. Assign an owner, track acknowledgement and escalate overdue actions.</p><p class="small">This preview stores preferences only. No emails, SMS or push messages are sent.</p>`)}</div>`)}
return '';
}
function safeUrl(value){try{const u=new URL(value);return u.protocol==='https:'?u.href:'#'}catch{return '#'}}
function bind(page,c){init(c);const s=c.store,$=q=>document.querySelector(q);const on=(id,event,fn)=>{const el=$(id);if(el)el.addEventListener(event,fn)};const form=(id,fn)=>on(id,'submit',ev=>{ev.preventDefault();fn(Object.fromEntries(new FormData(ev.target)));refresh(page,c)});on('#staff-project','change',ev=>{s.staffProjectId=ev.target.value;c.navigate(page)});
on('#staff-lead','change',ev=>{s.staffLead=Number(ev.target.value);refresh(page,c)});
on('#staff-add-line','click',()=>{const el=$('#staff-lines'),i=el.children.length;el.insertAdjacentHTML('beforeend',`<div class="staff-price-line"><input aria-label="Item ${i+1}" name="item${i}" required placeholder="Item"><input aria-label="Quantity ${i+1}" name="qty${i}" type="number" min="0" step="0.01" value="1" required><input aria-label="Rate ${i+1}" name="rate${i}" type="number" min="0" step="0.01" value="0" required></div>`)});
form('#staff-quote',d=>{const i=s.staffLead??0,lines=[];for(let n=0;d[`item${n}`]!==undefined;n++)lines.push({name:d[`item${n}`],qty:Number(d[`qty${n}`]),rate:Number(d[`rate${n}`])});const q={leadIndex:i,reference:d.reference,validUntil:d.validUntil,stage:d.stage,scope:d.scope,lines,updatedAt:stamp()};const old=s.quotes.findIndex(x=>x.leadIndex===i);if(old<0)s.quotes.push(q);else s.quotes[old]=q;if(c.leads[i])c.leads[i].stage=d.stage;c.toast('Demo estimate and pipeline saved')});
form('#staff-note',d=>{s.leadNotes.unshift({...d,id:uid(),leadIndex:s.staffLead??0,createdAt:stamp()});c.toast('Lead note added')});
on('#staff-seed','click',()=>{if(s.inventory.some(x=>x.projectId===c.projectId)){c.toast('A register already exists. Add individual items below.');return}for(const [category,items]of Object.entries(categories))for(const name of items)s.inventory.push({id:uid(),projectId:c.projectId,category,name,qty:0,unit:'ea',spec:'',supplier:'',orderReference:'',status:'To specify',visibility:['staff','customer','contractor']});refresh(page,c)});
form('#staff-inventory',d=>{const item={...d,id:d.id||uid(),projectId:c.projectId,qty:Number(d.qty),visibility:['staff','customer','contractor']};const i=s.inventory.findIndex(x=>x.id===item.id);if(i<0)s.inventory.push(item);else s.inventory[i]=item;emit(c,'Kitset inventory updated',`${d.name}: ${d.status}`,'inventory');c.toast('Kitset register updated')});
document.querySelectorAll('[data-staff-edit]').forEach(el=>el.onclick=()=>{const item=s.inventory.find(x=>x.id===el.dataset.staffEdit),f=$('#staff-inventory');for(const [k,v]of Object.entries(item))if(f.elements[k])f.elements[k].value=v;f.scrollIntoView({behavior:'smooth',block:'center'})});
form('#staff-document',d=>{if(safeUrl(d.url)==='#'){c.toast('Use a valid HTTPS link');return}s.documents.unshift({id:uid(),projectId:c.projectId,name:d.name,type:d.type,version:d.version,status:d.status,url:d.url,uploadedAt:stamp(),visibility:d.audience==='all'?['staff','customer','contractor']:d.audience==='customer'?['staff','customer']:['staff']});c.notify({title:'Project document added',message:`${d.name} · ${d.status}`,roles:d.audience==='all'?['staff','customer','contractor']:d.audience==='customer'?['staff','customer']:['staff'],projectId:c.projectId,kind:'document'});c.toast('Document registered')});
form('#staff-agreement',d=>{const a={...d,id:uid(),projectId:c.projectId,status:'Unreviewed draft',updatedAt:stamp()},i=s.agreements.findIndex(x=>x.projectId===c.projectId);if(i<0)s.agreements.push(a);else s.agreements[i]=a;c.toast('Unreviewed agreement draft saved')});
form('#staff-fees',d=>{s.fees={contractorMonthly:d.contractorMonthly===''?null:Number(d.contractorMonthly),customerTender:d.customerTender===''?null:Number(d.customerTender),gstRate:15};c.toast('Proposed fees saved. Billing remains inactive.')});
form('#staff-preferences',d=>{s.preferences.staff={inApp:d.inApp==='on',email:d.email==='on',urgentSms:d.urgentSms==='on',digest:d.digest};c.toast('Demo preferences saved')});
document.querySelectorAll('[data-staff-read]').forEach(el=>el.onclick=()=>{const n=s.notifications.find(x=>x.id===el.dataset.staffRead);if(n){n.readBy||=[];if(!n.readBy.includes('staff'))n.readBy.push('staff');refresh(page,c)}});
}
window.SHStaff={pages,render,bind};
})();
